contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint a, uint b, uint x, uint y) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a) + (b) + (x) + (y)); require(a <= 1000000000000000000000000000000); require(b <= 1000000000000000000000000000000); require(x <= 1000000000000000000000000000000); require(y <= 1000000000000000000000000000000);
        require(x <= a && y <= b);
        require(address(this).balance >= a + b);
        require(a < type(uint).max - b);
        require(address(this).balance >= x && address(this).balance >= y);

        uint initialC = address(c).balance;

        c.deposit{value: a}(); if (__ESBMC_reverted()) return;
        c.deposit{value: b}(); if (__ESBMC_reverted()) return;

        c.withdrawAll(); if (__ESBMC_reverted()) return;
        c.withdrawAll(); if (__ESBMC_reverted()) return;

        c.deposit{value: x}(); if (__ESBMC_reverted()) return;
        c.deposit{value: y}(); if (__ESBMC_reverted()) return;

        uint finalC = address(c).balance;

        assert(finalC >= initialC);
    }

    receive() external payable {}
}

