pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 a, uint256 b, uint256 x, uint256 y) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        b = bound(b, 0, 1000000000000000000000000000000);
        x = bound(x, 0, 1000000000000000000000000000000);
        y = bound(y, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP + VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(x <= a && y <= b);
        vm.assume(address(this).balance >= a + b);
        vm.assume(a < type(uint).max - b);
        vm.assume(address(this).balance >= x && address(this).balance >= y);
        uint initialC = address(c).balance;
        try c.deposit{value: a}() {} catch { return; }
        try c.deposit{value: b}() {} catch { return; }
        try c.withdrawAll() {} catch { return; }
        try c.withdrawAll() {} catch { return; }
        try c.deposit{value: x}() {} catch { return; }
        try c.deposit{value: y}() {} catch { return; }
        uint finalC = address(c).balance;
        assertTrue(finalC >= initialC);
    }

    function testFuzz_run(uint256 a, uint256 b, uint256 x, uint256 y) public {
        _run(a, b, x, y);
    }

    receive() external payable {}
}
